$counts = [
 'Pujas' => (int)$pdo->query('SELECT COUNT(*) FROM pujas')->fetchColumn(),
 'Services' => (int)$pdo->query('SELECT COUNT(*) FROM services')->fetchColumn(),
 'Partners' => (int)$pdo->query('SELECT COUNT(*) FROM partners')->fetchColumn(),
 'Team members' => (int)$pdo->query('SELECT COUNT(*) FROM team_members')->fetchColumn(),
 'Feedback' => (int)$pdo->query('SELECT COUNT(*) FROM feedback')->fetchColumn(),
];
$pujas = $pdo->query('SELECT id,name_en,name_bn,category,published,map_url FROM pujas ORDER BY id DESC')->fetchAll();
$services = $pdo->query('SELECT id,name_en,service_type,phone,published FROM services ORDER BY id DESC')->fetchAll();
$contacts = $pdo->query('SELECT * FROM emergency_contacts ORDER BY sort_order,id')->fetchAll();
$partners = $pdo->query('SELECT * FROM partners ORDER BY sort_order,id')->fetchAll();
$team = $pdo->query('SELECT * FROM team_members ORDER BY sort_order,id')->fetchAll();
$feedback = $pdo->query('SELECT * FROM feedback ORDER BY created_at DESC LIMIT 100')->fetchAll();
$ratingSummary = $pdo->query('SELECT p.name_en, COUNT(r.id) AS votes, ROUND(AVG(r.rating),1) AS average_rating FROM pujas p LEFT JOIN puja_ratings r ON r.puja_id=p.id GROUP BY p.id ORDER BY average_rating DESC, votes DESC')->fetchAll();
function selected($a,$b){return $a===$b?'selected':'';}
function checked($v){return $v?'checked':'';}
